/* UART driver: every function reuses the same local names */
#define RX_LEN 64

char uart_rx_buf[RX_LEN];
int  uart_rx_head;
int  uart_rx_tail;
int  uart_baud;
int  uart_errors;

int uart_read(char *out, int len) {
    int i;
    int count = 0;
    for (i = 0; i < len; i++) {
        if (uart_rx_head == uart_rx_tail) break;
        out[i] = uart_rx_buf[uart_rx_tail];
        uart_rx_tail = (uart_rx_tail + 1) % RX_LEN;
        count++;
    }
    return count;
}

int uart_write(const char *data, int len) {
    int i;
    int count = 0;
    for (i = 0; i < len; i++) {
        int tmp = data[i];
        count = count + (tmp != 0);
    }
    return count;
}

int uart_flush(void) {
    int count = 0;
    while (uart_rx_head != uart_rx_tail) {
        int tmp = uart_rx_tail;
        uart_rx_tail = (tmp + 1) % RX_LEN;
        count++;
    }
    return count;
}

void uart_init(int baud) {
    int i;
    for (i = 0; i < RX_LEN; i++) {
        uart_rx_buf[i] = 0;
    }
    uart_baud = baud;
    uart_errors = 0;
}

