/* Multi-tier Scope Tracking */
int global_system_state;
int global_error_counter;
int sample_rate;

int compute_metrics(int input_factor, int sample_rate) {
    int local_accumulator = 0;
    int local_threshold = input_factor * sample_rate;

    for (int loop_i = 0; loop_i < 100; loop_i++) {
        int block_sample = loop_i * input_factor;
        if (block_sample > local_threshold) {
            int local_threshold = block_sample / 2;
            local_accumulator += local_threshold;
        }
    }

    global_error_counter = global_error_counter + 1;
    return local_accumulator;
}

